/** A reply must anchor to a live, top-level comment on the same issue. */
async function assertValidParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId | null,
): Promise<void> {
  if (parentId === null) return;

  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (
    !parent ||
    parent.issueId !== issueId ||
    parent.parentId !== null ||
    isArchived(parent)
  ) {
    throw new NotFoundError("Comment", parentId);
  }
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. Whoever the composer's suggestions name,
 * only ids that are still active members of this org survive — a stranger or
 * someone who has left is dropped rather than notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const activeMembers: readonly MemberWithUser[] = members.items.filter(
    (member) => member.status === "active",
  );
  const activeUserIds = new Set(activeMembers.map((member) => member.userId));

  const resolved = resolveMentions(body, activeMembers);
  const validClientProvided = clientProvided.filter((id) =>
    activeUserIds.has(id),
  );

  return [...new Set([...resolved, ...validClientProvided])];
}

